        () {
      final run = restoreStep()['run'] as String;
      final curlIndex = run.indexOf(RegExp(r'^\s*curl\s', multiLine: true));
      expect(curlIndex, greaterThan(0));
      final beforeCurl = run.substring(0, curlIndex);
      expect(
        beforeCurl,
