      if (!onFlagLine && !bare.startsWith('- ')) {
        positional.add(bare);
      }
    }
    blocks.add(CreateBlock(cmdLines.join('\n'), tag, title.isEmpty ? null : title.last, positional));
  }
  return blocks;
}

