      attempts,
      greaterThanOrEqualTo(1),
      reason: 'download loop `for … in $items` yields no attempts',
    );

    final curlStart = bodyLines.indexWhere(
      (l) => RegExp(r'^\s*(if\s+)?curl\s').hasMatch(l),
    );
