      header: header,
      body: bodyLines.join('\n'),
      attempts: attempts,
      curl: curl,
      sleepSeconds: sleep.isEmpty ? 0 : sleep.first,
    );
  }

  int? intFlag(String flag) {
    final m = RegExp('$flag (\\d+)').firstMatch(curl);
    return m == null ? null : int.parse(m.group(1)!);
  }
