      'the download starts from a fresh /tmp zip (deterministic -C - seed)',
      () {
        final run = restoreStep()['run'] as String;
        final loopStart = run.indexOf(
          RegExp(r'^\s*for\s+\w+\s+in\s+', multiLine: true),
        );
