        expect(
          beforeLoop,
          contains('rm -f /tmp/WasmRun.xcframework.zip'),
          reason:
              'a stale /tmp zip from a previous run must never seed -C - '
              'with an unknown byte offset — rm -f it before the loop so only '
              'THIS step\'s own partial bytes are resumed',
        );
      },
    );
  });
}

